pub fn wb_condition_desc_from_index(a_index: i32) -> Option<&'static TConditionFunction> {
    let mut result: Option<&'static TConditionFunction> = Default::default();
    result = None;
    let mut l: i32 = 0;
    let mut h: i32 = (WB_CONDITION_FUNCTIONS.len() as i32 - 1);
    while (l <= h) {
        let mut i: i32 = ((l + h) >> 1);
        let mut c: i32 = cmp_w32(
            ((WB_CONDITION_FUNCTIONS[(i) as usize].clone().index) as u32),
            ((a_index) as u32),
        );
        if (c < 0) {
            l = (i + 1);
        } else {
            h = (i - 1);
            if (c == 0) {
                l = i;
                result = Some(&WB_CONDITION_FUNCTIONS[(l) as usize]);
            }
        }
    }
    result
}

